+class M_wrapper(object):
+    # Wrapper around the expected M sage matrix.
+    # We call nrows() and ncols() frequently.
+    # Otherwise it's a scipy 64-bit-integer matrix.
+
+    def __init__(self, scipy_matrix, nrows, ncols):
+
+        self._nrows = nrows
+        self._ncols = ncols
+        self._scipy_M = scipy_matrix
+
+    def nrows(self):
+        return self._nrows
+
+    def ncols(self):
+        return self._ncols
+
+    def scipy_M(self):
+        return self._scipy_M
+
+def b2i(b, signed=False):
+    return int.from_bytes(b, 'little', signed=signed)
+
+def fast_col_parse_process(args):
+    batch_inline_data = []
+    batch_inline_col_weights = []
+    row_idx, rows = args
+    for row in rows:
+        byte_idx = 0
+        row_nbytes = len(row)
+        while byte_idx < row_nbytes:
+            col_bytes = row[byte_idx : byte_idx + 8]
+            col_idx = b2i(col_bytes[:4])
+            if col_idx >= len(batch_inline_col_weights):
+                pad = col_idx + 1 - len(batch_inline_col_weights)
+                batch_inline_col_weights += [0] * pad
+            batch_inline_col_weights[col_idx] += 1
+            val = b2i(col_bytes[4:], signed=True)
+            byte_idx += 8
+            batch_inline_data.append((row_idx, col_idx, val))
+        row_idx += 1
+
+    return batch_inline_col_weights, batch_inline_data
+
 
